        start_idx = 0
        end_idx = len(word)
        for char in word:
            code = ord(char)
            if code in valid_punctuation:
                if start_idx == 0:
                    start_idx = 1
                if end_idx == len(word) - 1:
                    end_idx = len(word) - 2
            else:
                break
        return start_idx > 0 and end_idx < len(word) - 1

